INSERT INTO "resolutions" VALUES(1,1,3,'Rebuilt the catalogue search index and restarted the search service.','The nightly index job failed after a disk-space warning.','2026-11-14 15:33:25.981999');
INSERT INTO "resolutions" VALUES(2,2,4,'Replaced the paper feed roller and cleaned the paper path.','Worn feed roller.','2026-11-15 16:33:25.981999');
INSERT INTO "resolutions" VALUES(3,3,2,'Re-authorised the sync client and cleared the stuck upload queue.','Expired sync token after a password policy change.','2026-11-16 17:33:25.981999');
INSERT INTO "resolutions" VALUES(4,4,2,'Synchronised the directory replica and cleared the cached credentials.','A stale directory replica rejected newly changed passwords.','2026-11-17 13:58:25.981999');
INSERT INTO "resolutions" VALUES(5,5,3,'Added a missing index on the timetable query and recycled the application pool.','Full table scan caused by a missing index.','2026-11-18 08:53:25.981999');
INSERT INTO "resolutions" VALUES(6,6,3,'Cleared the stuck outbound queue and restarted the mail relay.','A large message blocked the relay queue.','2026-11-18 19:03:25.981999');
INSERT INTO "resolutions" VALUES(7,7,2,'Replaced the faulty access point and moved clients to the new radio channel.','Failing access point firmware.','2026-11-19 09:03:25.981999');
INSERT INTO "resolutions" VALUES(8,8,3,'Increased the outbound message size limit to 25 MB.','Limit was reset to a default after the last server update.','2026-11-19 11:33:25.981999');
